 @Override protected void onSaveInstanceState(Bundle out){out.putInt("newest",newest);super.onSaveInstanceState(out);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);openRequested(intent);}
 private void openRequested(Intent intent){if(intent==null||!intent.hasExtra("open_space"))return;int id=intent.getIntExtra("open_space",-1);String token=intent.getStringExtra("space_generation");intent.removeExtra("open_space");if(id>=1&&id<=32){if(SpacesController.shortcutValid(this,id,token))open(id);else{SpacesController.status(this,"这个快捷方式对应的空间已失效，请重新添加");Toast.makeText(this,"空间已删除或快捷方式已失效",Toast.LENGTH_LONG).show();}}}
 @Override protected void onResume(){super.onResume();resumedHere=true;refresh();SpacesController.check(this);}
 @Override protected void onPause(){resumedHere=false;super.onPause();}
 @Override protected void onDestroy(){unregisterReceiver(launchEvents);launchHandler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void networkSettings(){if(!busy)startActivity(new Intent(this,NetworkSettingsActivity.class));}
 private void showSettings(){new AlertDialog.Builder(this).setTitle("设置与帮助").setItems(new String[]{"网络与 IP 虚拟定位","使用说明","关于多开空间"},(d,i)->{if(i==0)networkSettings();else if(i==1)new AlertDialog.Builder(this).setTitle("使用说明").setMessage("请保留手机上的原版 WhatsApp。每个空间独立登录，原版更新后可同步全部空间。\n\n请先连接 v2rayNG，并把多开空间纳入 VPN。网络与定位中可以选择仅 VPN，或 VPN＋住宅代理。关闭住宅代理后，上次凭据仍会保留。\n\nIP 虚拟定位使用出口的估算位置，只作用于本应用的分身。具体定位接口兼容性仍在验证。\n\n当前网络功能为 TCP 实验版，语音和视频暂不保证可用。现有空壳分身数据不会迁入。").setPositiveButton("知道了",null).show();else new AlertDialog.Builder(this).setTitle("多开空间").setMessage("版本 0.3.3-test\nAndroid 16 兼容性测试版\n\n开源组件：BlackBox Reborn · 本地修改版").setPositiveButton("完成",null).show();}).show();}
 private interface Action{int run()throws Exception;}
 private void setBusy(boolean value,String message){busy=value;Ui.enabled(add,!value);Ui.enabled(sync,!value);Ui.enabled(auto,!value);Ui.enabled(network,!value);Ui.enabled(settings,!value);for(View v:spaceActions)Ui.enabled(v,!value);if(message!=null){status.setVisibility(View.VISIBLE);status.setText(message);}}
 private void task(Action action,String message){if(busy)return;setBusy(true,message);SpacesController.WORK.execute(()->{String error=null;int created=-1;try{created=action.run();}catch(Throwable e){error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();SpacesController.status(this,"操作未完成："+error);android.util.Log.e("WhatsAppSpaces","operation_failed",e);}String failure=error;int id=created;runOnUiThread(()->{if(isDestroyed())return;if(id>0)newest=id;rendered="";setBusy(false,null);if(failure!=null)new AlertDialog.Builder(this).setTitle("操作未完成").setMessage(failure).setPositiveButton("知道了",null).show();refresh();});});}
 private void refresh(){if(busy)return;SpacesController.WORK.execute(()->{String sourceText;java.util.List<Integer> ids=Collections.emptyList();try{PackageInfo p=SpacesController.source(this);sourceText="原版 WhatsApp  "+p.versionName;ids=SpacesController.spaces();}catch(Throwable e){sourceText="请先安装原版 WhatsApp，再添加空间";}String source=sourceText;java.util.List<Integer> found=ids;runOnUiThread(()->{if(isDestroyed()||busy)return;version.setText(source);count.setText(String.valueOf(found.size()));boolean use=NetworkOptions.residential(this),geo=NetworkOptions.location(this);badges.removeAllViews();badges.addView(Ui.badge(this,use?"VPN＋住宅代理":"仅使用 VPN",true,"lock"));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.leftMargin=dp(8);badges.addView(Ui.badge(this,geo?"IP 定位已开启":"IP 定位已关闭",geo,"pin"),bp);network.setContentDescription("网络与定位，"+(use?"VPN 加住宅代理":"仅使用 VPN")+"，IP 定位"+(geo?"已开启":"已关闭")+"，点击设置");String message=SpacesApplication.initializationError!=null?"引擎初始化失败，请稍后重试":SpacesController.prefs(this).getString("status","");status.setText(message);status.setVisibility(message.isEmpty()?View.GONE:View.VISIBLE);String key=found.toString()+":"+newest;for(int space:found)key+=":"+SpacesController.name(this,space)+":"+SpacesController.deleting(this,space);if(!key.equals(rendered)){rendered=key;renderSpaces(found);}});});}
 private void renderSpaces(java.util.List<Integer> ids){list.removeAllViews();spaceActions.clear();if(ids.isEmpty()){LinearLayout empty=Ui.card(this);TextView title=Ui.text(this,"为你的账号，添加一个空间",17,Ui.INK,true);title.setGravity(Gravity.CENTER);Ui.add(empty,title,8);TextView help=Ui.note(empty,"各空间独立登录。点击下方按钮开始。");help.setGravity(Gravity.CENTER);Ui.add(list,empty,8);return;}
  for(int id:ids){String spaceName=SpacesController.name(this,id);boolean removing=SpacesController.deleting(this,id);LinearLayout card=Ui.card(this);Ui.pad(card,12,10);LinearLayout top=Ui.row(this);FrameLayout avatar=new FrameLayout(this);ImageView image=new ImageView(this);try{image.setImageDrawable(getPackageManager().getApplicationIcon(SpacesController.SOURCE));}catch(Exception e){image.setImageDrawable(Ui.symbol(this,"logo",Ui.GREEN,46));}image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);avatar.addView(image,new FrameLayout.LayoutParams(dp(44),dp(44),Gravity.TOP|Gravity.LEFT));TextView number=Ui.text(this,String.valueOf(id),12,Ui.GREEN,true);number.setGravity(Gravity.CENTER);number.setBackground(Ui.shape(this,Ui.PALE,12,0));avatar.addView(number,new FrameLayout.LayoutParams(dp(23),dp(23),Gravity.BOTTOM|Gravity.RIGHT));top.addView(avatar,new LinearLayout.LayoutParams(dp(51),dp(51)));
   LinearLayout words=Ui.column(this);LinearLayout nameRow=Ui.row(this);TextView name=Ui.text(this,spaceName,19,Ui.INK,true);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);nameRow.addView(name,new LinearLayout.LayoutParams(0,-2,1));if(id==newest){TextView tag=Ui.badge(this,"新建",true,null);tag.setTextSize(10);Ui.pad(tag,6,3);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-2,-2);tp.leftMargin=dp(6);nameRow.addView(tag,tp);}words.addView(nameRow);TextView subtitle=Ui.text(this,removing?"清理未完成 · 请再次删除":"独立空间 · "+id,12,Ui.MUTED,false);Ui.add(words,subtitle,6);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,-2,1);wp.leftMargin=dp(11);top.addView(words,wp);ImageButton more=Ui.iconButton(this,"more",spaceName+" 的更多操作",()->{});more.setOnClickListener(v->{PopupMenu menu=new PopupMenu(this,v);menu.getMenu().add("打开空间").setEnabled(!removing).setOnMenuItemClickListener(item->{open(id);return true;});menu.getMenu().add("添加到桌面").setEnabled(!removing).setOnMenuItemClickListener(item->{pin(id);return true;});menu.getMenu().add("重新启动空间").setEnabled(!removing).setOnMenuItemClickListener(item->{restart(id);return true;});menu.getMenu().add("重命名").setEnabled(!removing).setOnMenuItemClickListener(item->{rename(id);return true;});menu.getMenu().add(removing?"重试删除":"删除分身").setOnMenuItemClickListener(item->{confirmDelete(id);return true;});menu.show();});top.addView(more,new LinearLayout.LayoutParams(dp(40),dp(48)));spaceActions.add(more);card.addView(top);
   LinearLayout actions=Ui.row(this);actions.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);Button desktop=Ui.button(this,"添加到桌面","external",false,()->pin(id));desktop.setContentDescription("添加 "+spaceName+" 到桌面");actions.addView(desktop,new LinearLayout.LayoutParams(-2,dp(48)));Button launch=Ui.button(this,"打开","play",true,()->open(id));launch.setContentDescription("打开 "+spaceName);LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(dp(90),dp(48));op.leftMargin=dp(9);actions.addView(launch,op);if(removing){Ui.enabled(desktop,false);Ui.enabled(launch,false);}else{spaceActions.add(desktop);spaceActions.add(launch);}Ui.add(card,actions,8);Ui.add(list,card,9);
  }
 }
 private void rename(int id){if(busy)return;EditText input=new EditText(this);input.setSingleLine(true);input.setTextSize(17);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setText(SpacesController.name(this,id));input.setSelection(input.length());Ui.pad(input,16,12);LinearLayout box=Ui.column(this);Ui.pad(box,20,8);box.addView(input,new LinearLayout.LayoutParams(-1,-2));Ui.note(box,"1–24 个字符；名称会保存在本机。");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("重命名分身").setView(box).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(w->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String value=SpacesController.validName(input.getText().toString());dialog.dismiss();task(()->{SpacesController.rename(this,id,value);return 0;},"正在保存名称…");}catch(IllegalArgumentException e){input.setError(e.getMessage());}}));dialog.show();}
 private void confirmDelete(int id){if(busy)return;String name=SpacesController.name(this,id);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("删除「"+name+"」？").setMessage("将永久清除这个分身在本机的登录状态、聊天记录和文件，无法撤销。\n\n其他分身和手机上的原版 WhatsApp 不受影响。已添加的桌面快捷方式将停用。").setNegativeButton("取消",null).setPositiveButton("删除分身",(d,w)->task(()->{SpacesController.remove(this,id);if(newest==id)newest=-1;return 0;},"正在删除空间…")).create();dialog.setOnShowListener(w->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setTextColor(0xffc23b36));dialog.show();}
 private void restart(int id){if(busy)return;new AlertDialog.Builder(this).setTitle("重新启动空间？").setMessage("将关闭「"+SpacesController.name(this,id)+"」的运行进程并重新打开，保留登录状态和本地数据。").setNegativeButton("取消",null).setPositiveButton("重新启动",(d,w)->open(id,true)).show();}
 private void open(int id){open(id,false);}
 private void stage(String text){runOnUiThread(()->{if(!isDestroyed()&&busy)status.setText(text);});}
 private void open(int id,boolean restart){if(busy)return;setBusy(true,"正在检查空间…");SpacesController.WORK.execute(()->{
  String error=null,phase="space";
  try{
   if(SpacesController.deleting(this,id))throw new java.io.IOException("空间正在删除，请先完成清理");
   SpacesController.sync(this,false);phase="vpn";stage("正在检查 VPN 与转发服务…");ResidentialService.prepare(this);
   ResidentialService.State state=ResidentialService.State.read(this);String session=android.util.Base64.encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(state.token),android.util.Base64.NO_WRAP);
   String last=SpacesController.prefs(this).getString("relaySession."+id,null);
   if(restart||(last!=null&&!session.equals(last))){stage("正在恢复空间进程…");top.niunaijun.blackbox.BlackBoxCore.get().stopPackage(SpacesController.SOURCE,id);}
   phase="location";stage(NetworkOptions.location(this)?"正在查询出口位置，请稍候…":"正在准备空间…");IpLocation.beforeOpen(this);
   SpacesController.prefs(this).edit().putString("relaySession."+id,session).apply();
  }catch(Throwable e){error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();android.util.Log.w("WhatsAppSpaces","launch_prepare_failed stage="+phase+" type="+e.getClass().getSimpleName());}
  String failure=error;runOnUiThread(()->{
   if(isDestroyed())return;if(failure!=null){setBusy(false,null);SpacesController.status(this,"暂时无法打开："+failure);refresh();if(resumedHere)new AlertDialog.Builder(this).setTitle("空间暂时无法打开").setMessage(failure).setNegativeButton("关闭",null).setNeutralButton("网络设置",(d,w)->networkSettings()).setPositiveButton("重试",(d,w)->open(id,restart)).show();return;}
   awaitingSpace=id;requestedAt=SystemClock.elapsedRealtime();status.setText("正在等待分身页面打开…");
   try{if(!SpacesController.open(id))throw new IllegalStateException("引擎未接受启动请求");android.util.Log.i("WhatsAppSpaces","launch_submitted id="+id);launchHandler.postDelayed(()->{if(awaitingSpace!=id)return;awaitingSpace=-1;setBusy(false,null);SpacesController.status(this,"尚未确认空间打开，可在菜单选择重新启动空间");android.util.Log.w("WhatsAppSpaces","launch_confirmation_timeout space="+id);refresh();if(resumedHere)new AlertDialog.Builder(this).setTitle("未确认分身页面打开").setMessage("可以重新启动此空间的进程后再试，登录状态和本地数据会保留。").setNegativeButton("稍后",null).setPositiveButton("重新启动",(d,w)->open(id,true)).show();},12000);
   }catch(Throwable e){awaitingSpace=-1;setBusy(false,null);SpacesController.status(this,"启动失败，请重新启动空间");android.util.Log.w("WhatsAppSpaces","launch_dispatch_failed type="+e.getClass().getSimpleName());refresh();}
  });
 });}
 private void pin(int id){ShortcutManager shortcuts=getSystemService(ShortcutManager.class);if(shortcuts==null||!shortcuts.isRequestPinShortcutSupported()){Toast.makeText(this,"当前桌面不支持添加快捷方式",Toast.LENGTH_LONG).show();return;}Intent intent=SpacesController.shortcutIntent(this,id);Icon icon=Icon.createWithResource(this,com.yshut.whatsappspaces.R.drawable.app_mark);try{Drawable original=getPackageManager().getApplicationIcon(SpacesController.SOURCE);Bitmap bitmap=Bitmap.createBitmap(144,144,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);original.setBounds(0,0,144,144);original.draw(canvas);Paint paint=new Paint(3);paint.setColor(Ui.GREEN);canvas.drawCircle(118,118,26,paint);paint.setColor(Color.WHITE);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextSize(30);paint.setTextAlign(Paint.Align.CENTER);canvas.drawText(String.valueOf(id),118,128,paint);icon=Icon.createWithBitmap(bitmap);}catch(Exception ignored){}ShortcutInfo info=new ShortcutInfo.Builder(this,SpacesController.shortcutId(this,id)).setShortLabel(SpacesController.name(this,id)).setLongLabel(SpacesController.name(this,id)).setIcon(icon).setIntent(intent).build();shortcuts.requestPinShortcut(info,null);}
